using System.Data;
using Dapper;
using IntegraRP.Application.Commercial;
using IntegraRP.Contracts.Commercial;
using IntegraRP.Infrastructure.Data;

namespace IntegraRP.Infrastructure.Repositories.Postgres.Commercial;

public sealed class PostgresOrderConfirmationRepository(IDbConnectionFactory connectionFactory) : ICommercialJourneyRepository, IOrderConfirmationService
{
    public async Task<CustomerDetailDto> CreateCustomerAsync(Guid tenantId, Guid userId, CreateCustomerRequest request, string correlationId, CancellationToken ct)
    {
        ValidateContext(tenantId, userId); if (string.IsNullOrWhiteSpace(request.Name)) throw new ArgumentException("Nome obrigatório.");
        using var c = await connectionFactory.OpenConnectionAsync(ct); using var tx = c.BeginTransaction(); var now = DateTimeOffset.UtcNow; var id = Guid.NewGuid(); var doc = Normalize(request.Document);
        await c.ExecuteAsync(new CommandDefinition("""
insert into integrarp.cliente(id,tenant_id,nome,documento_normalizado,email,telefone,status,row_version,criado_em,atualizado_em,correlation_id)
values(@id,@tenantId,@name,@doc,@email,@phone,'ativo',1,@now,@now,@correlationId);
insert into integrarp.auditoria_evento(id,tenant_id,usuario_id,entidade,entidade_id,acao,depois_json,correlation_id,criado_em,origem)
values(gen_random_uuid(),@tenantId,@userId,'cliente',@id,'cliente.criado',jsonb_build_object('nome',@name),@correlationId,@now,'api');
""", new { id, tenantId, userId, name = request.Name.Trim(), doc, email = request.Email, phone = request.Phone, now, correlationId }, tx, cancellationToken: ct)); tx.Commit();
        return new CustomerDetailDto(id, tenantId, request.Name.Trim(), doc, request.Email, request.Phone, "ativo", 1, now, now);
    }
    public async Task<ProductCategoryDto> CreateCategoryAsync(Guid tenantId, Guid userId, CreateProductCategoryRequest request, string correlationId, CancellationToken ct)
    { ValidateContext(tenantId,userId); using var c=await connectionFactory.OpenConnectionAsync(ct); using var tx=c.BeginTransaction(); var id=Guid.NewGuid(); await c.ExecuteAsync(new CommandDefinition("insert into integrarp.produto_categoria(id,tenant_id,codigo,nome,status,row_version,criado_em,atualizado_em,correlation_id) values(@id,@tenantId,@code,@name,'ativo',1,now(),now(),@correlationId)", new{id,tenantId,code=request.Code.Trim(),name=request.Name.Trim(),correlationId}, tx, cancellationToken:ct)); tx.Commit(); return new ProductCategoryDto(id,request.Code.Trim(),request.Name.Trim(),"ativo",1); }
    public async Task<ProductDetailDto> CreateProductAsync(Guid tenantId, Guid userId, CreateProductRequest request, string correlationId, CancellationToken ct)
    { ValidateContext(tenantId,userId); if(request.CategoryId==default) throw new ArgumentException("Categoria obrigatória."); using var c=await connectionFactory.OpenConnectionAsync(ct); using var tx=c.BeginTransaction(); var category=await c.QuerySingleOrDefaultAsync<string>(new CommandDefinition("select nome from integrarp.produto_categoria where tenant_id=@tenantId and id=@CategoryId and status='ativo' and excluido_em is null", new{tenantId,request.CategoryId}, tx, cancellationToken:ct)); if(category is null){throw new InvalidOperationException("Categoria ativa não encontrada.");} var id=Guid.NewGuid(); await c.ExecuteAsync(new CommandDefinition("insert into integrarp.produto(id,tenant_id,sku,categoria_id,nome,preco,estoque_minimo,status,row_version,criado_em,atualizado_em,correlation_id) values(@id,@tenantId,@sku,@CategoryId,@name,@Price,@MinimumStock,'ativo',1,now(),now(),@correlationId)", new{id,tenantId,sku=request.Sku.Trim(),request.CategoryId,name=request.Name.Trim(),request.Price,request.MinimumStock,correlationId}, tx, cancellationToken:ct)); tx.Commit(); return new ProductDetailDto(id,tenantId,request.Sku.Trim(),request.Name.Trim(),request.CategoryId,category,request.Price,request.MinimumStock,"ativo",1); }
    public async Task<InventoryMovementDto> RegisterEntryAsync(Guid tenantId, Guid userId, CreateStockEntryRequest request, string correlationId, CancellationToken ct)
    { ValidateContext(tenantId,userId); if(request.Quantity<=0) throw new ArgumentException("Quantidade deve ser maior que zero."); using var c=await connectionFactory.OpenConnectionAsync(ct); using var tx=c.BeginTransaction(); var existing=await c.QuerySingleOrDefaultAsync<Guid?>(new CommandDefinition("select id from integrarp.estoque_movimento where tenant_id=@tenantId and idempotency_key=@IdempotencyKey", new{tenantId,request.IdempotencyKey}, tx, cancellationToken:ct)); if(existing is Guid eid){tx.Commit(); return new InventoryMovementDto(eid,request.ProductId,"entrada",request.Quantity,request.LocationCode,request.Reason,correlationId,DateTimeOffset.UtcNow);} var id=Guid.NewGuid(); await c.ExecuteAsync(new CommandDefinition("""
insert into integrarp.estoque_saldo(id,tenant_id,produto_id,local_codigo,saldo_fisico,saldo_reservado,row_version,criado_em,atualizado_em) values(gen_random_uuid(),@tenantId,@ProductId,@LocationCode,0,0,1,now(),now()) on conflict(tenant_id,produto_id,local_codigo) do nothing;
update integrarp.estoque_saldo set saldo_fisico=saldo_fisico+@Quantity, row_version=row_version+1, atualizado_em=now() where tenant_id=@tenantId and produto_id=@ProductId and local_codigo=@LocationCode;
insert into integrarp.estoque_movimento(id,tenant_id,produto_id,tipo,quantidade,local_codigo,motivo,usuario_id,idempotency_key,correlation_id,criado_em) values(@id,@tenantId,@ProductId,'entrada',@Quantity,@LocationCode,@Reason,@userId,@IdempotencyKey,@correlationId,now());
""", new{id,tenantId,userId,request.ProductId,request.Quantity,request.LocationCode,request.Reason,request.IdempotencyKey,correlationId}, tx, cancellationToken:ct)); tx.Commit(); return new InventoryMovementDto(id,request.ProductId,"entrada",request.Quantity,request.LocationCode,request.Reason,correlationId,DateTimeOffset.UtcNow); }
    public async Task<OrderDetailDto> CreateOrderAsync(Guid tenantId, Guid userId, CreateOrderRequest request, string correlationId, CancellationToken ct){ ValidateContext(tenantId,userId); using var c=await connectionFactory.OpenConnectionAsync(ct); using var tx=c.BeginTransaction(); var customer=await c.QuerySingleOrDefaultAsync<string>(new CommandDefinition("select nome from integrarp.cliente where tenant_id=@tenantId and id=@CustomerId and status='ativo' and excluido_em is null",new{tenantId,request.CustomerId},tx,cancellationToken:ct)); if(customer is null){throw new InvalidOperationException("Cliente ativo não encontrado.");} var existing=await c.QuerySingleOrDefaultAsync<(Guid Id,string Number)>(new CommandDefinition("select id Id,numero Number from integrarp.pedido where tenant_id=@tenantId and idempotency_key=@IdempotencyKey",new{tenantId,request.IdempotencyKey},tx,cancellationToken:ct)); if(existing.Id!=Guid.Empty){tx.Commit(); return new OrderDetailDto(existing.Id,tenantId,existing.Number,request.CustomerId,customer,"rascunho",[],0,1);} await c.ExecuteAsync(new CommandDefinition("select pg_advisory_xact_lock(hashtextextended(@tenantId::text, 132))",new{tenantId},tx,cancellationToken:ct)); var sequence=await c.QuerySingleAsync<long>(new CommandDefinition("select coalesce(max(substring(numero from 10)::bigint),0)+1 from integrarp.pedido where tenant_id=@tenantId and numero like @prefix",new{tenantId,prefix=$"PED-{DateTimeOffset.UtcNow:yyyy}-%"},tx,cancellationToken:ct)); var id=Guid.NewGuid(); var number=$"PED-{DateTimeOffset.UtcNow:yyyy}-{sequence:000000}"; await c.ExecuteAsync(new CommandDefinition("insert into integrarp.pedido(id,tenant_id,numero,cliente_id,status,total,row_version,idempotency_key,criado_em,atualizado_em,correlation_id) values(@id,@tenantId,@number,@CustomerId,'rascunho',0,1,@IdempotencyKey,now(),now(),@correlationId)",new{id,tenantId,number,request.CustomerId,request.IdempotencyKey,correlationId},tx,cancellationToken:ct)); tx.Commit(); return new OrderDetailDto(id,tenantId,number,request.CustomerId,customer,"rascunho",[],0,1); }
    public async Task<OrderDetailDto> AddOrderItemAsync(Guid tenantId, Guid userId, Guid orderId, AddOrderItemRequest request, string correlationId, CancellationToken ct){ ValidateContext(tenantId,userId); using var c=await connectionFactory.OpenConnectionAsync(ct); using var tx=c.BeginTransaction(); var order=await c.QuerySingleAsync<(Guid CustomerId,string Number,string CustomerName,string Status,long RowVersion)>(new CommandDefinition("select p.cliente_id CustomerId,p.numero Number,c.nome CustomerName,p.status Status,p.row_version RowVersion from integrarp.pedido p join integrarp.cliente c on c.tenant_id=p.tenant_id and c.id=p.cliente_id where p.tenant_id=@tenantId and p.id=@orderId for update",new{tenantId,orderId},tx,cancellationToken:ct)); if(order.Status!="rascunho"){throw new InvalidOperationException("Somente rascunho aceita itens.");} var prod=await c.QuerySingleAsync<(string Sku,string Name)>(new CommandDefinition("select sku Sku,nome Name from integrarp.produto where tenant_id=@tenantId and id=@ProductId and status='ativo'",new{tenantId,request.ProductId},tx,cancellationToken:ct)); var itemId=Guid.NewGuid(); var total=request.Quantity*request.UnitPrice-request.Discount; await c.ExecuteAsync(new CommandDefinition("insert into integrarp.pedido_item(id,tenant_id,pedido_id,produto_id,quantidade,preco_unitario,desconto,total,idempotency_key,criado_em) values(@itemId,@tenantId,@orderId,@ProductId,@Quantity,@UnitPrice,@Discount,@total,@IdempotencyKey,now()); update integrarp.pedido set total=(select coalesce(sum(total),0) from integrarp.pedido_item where tenant_id=@tenantId and pedido_id=@orderId), row_version=row_version+1, atualizado_em=now() where tenant_id=@tenantId and id=@orderId",new{itemId,tenantId,orderId,request.ProductId,request.Quantity,request.UnitPrice,request.Discount,total,request.IdempotencyKey},tx,cancellationToken:ct)); tx.Commit(); return new OrderDetailDto(orderId,tenantId,order.Number,order.CustomerId,order.CustomerName,"rascunho",[new OrderItemDto(itemId,request.ProductId,prod.Sku,prod.Name,request.Quantity,request.UnitPrice,request.Discount,total)],total,order.RowVersion+1); }
    public async Task<TaskTransitionResultDto> ConfirmAsync(Guid tenantId, Guid userId, Guid orderId, ConfirmOrderRequest request, string correlationId, CancellationToken ct){ ValidateContext(tenantId,userId); using var c=await connectionFactory.OpenConnectionAsync(ct); using var tx=c.BeginTransaction(); try { var order=await c.QuerySingleOrDefaultAsync<(string Status,long RowVersion)>(new CommandDefinition("select status Status,row_version RowVersion from integrarp.pedido where tenant_id=@tenantId and id=@orderId for update",new{tenantId,orderId},tx,cancellationToken:ct)); if(order.Status is null) throw new KeyNotFoundException("Pedido não encontrado."); if(order.RowVersion!=request.RowVersion) throw new DBConcurrencyException(); if(order.Status=="em_separacao") { tx.Commit(); return new TaskTransitionResultDto(orderId,"em_separacao","em_separacao",order.RowVersion,correlationId);} if(order.Status!="rascunho") throw new InvalidOperationException("Transição inválida."); var items=(await c.QueryAsync<(Guid ProductId,decimal Quantity)>(new CommandDefinition("select produto_id ProductId,quantidade Quantity from integrarp.pedido_item where tenant_id=@tenantId and pedido_id=@orderId order by produto_id",new{tenantId,orderId},tx,cancellationToken:ct))).ToList(); if(items.Count==0) throw new InvalidOperationException("Pedido sem itens."); foreach(var item in items){ var available=await c.QuerySingleOrDefaultAsync<decimal>(new CommandDefinition("select saldo_fisico-saldo_reservado from integrarp.estoque_saldo where tenant_id=@tenantId and produto_id=@ProductId order by local_codigo for update",new{tenantId,item.ProductId},tx,cancellationToken:ct)); if(available<item.Quantity) throw new InvalidOperationException("Estoque insuficiente."); await c.ExecuteAsync(new CommandDefinition("update integrarp.estoque_saldo set saldo_reservado=saldo_reservado+@Quantity,row_version=row_version+1 where tenant_id=@tenantId and produto_id=@ProductId and local_codigo=(select local_codigo from integrarp.estoque_saldo where tenant_id=@tenantId and produto_id=@ProductId order by local_codigo limit 1); insert into integrarp.estoque_reserva(id,tenant_id,pedido_id,produto_id,quantidade,status,idempotency_key,correlation_id,criado_em) values(gen_random_uuid(),@tenantId,@orderId,@ProductId,@Quantity,'ativa',@IdempotencyKey,@correlationId,now()) on conflict(tenant_id,idempotency_key) do nothing",new{tenantId,orderId,item.ProductId,item.Quantity,request.IdempotencyKey,correlationId},tx,cancellationToken:ct)); } var taskId=Guid.NewGuid(); await c.ExecuteAsync(new CommandDefinition("update integrarp.pedido set status='em_separacao',row_version=row_version+1,atualizado_em=now() where tenant_id=@tenantId and id=@orderId; insert into integrarp.pedido_historico_status(id,tenant_id,pedido_id,status_anterior,status_novo,usuario_id,correlation_id,criado_em) values(gen_random_uuid(),@tenantId,@orderId,'rascunho','em_separacao',@userId,@correlationId,now()); insert into integrarp.tarefa_operacional(id,tenant_id,pedido_id,titulo,status,prioridade,sla_minutos,vencimento_em,checklist_resposta_json,row_version,correlation_id,criado_em,atualizado_em) values(@taskId,@tenantId,@orderId,'Separar pedido','aberta','normal',120,now()+interval '120 minutes','[]'::jsonb,1,@correlationId,now(),now()) on conflict(tenant_id,pedido_id) do nothing; insert into integrarp.outbox_evento(id,tenant_id,tipo,payload_json,status,tentativas,correlation_id,criado_em,atualizado_em) values(gen_random_uuid(),@tenantId,'pedido.confirmado',jsonb_build_object('pedidoId',@orderId),'pendente',0,@correlationId,now(),now());",new{tenantId,userId,orderId,taskId,correlationId},tx,cancellationToken:ct)); tx.Commit(); return new TaskTransitionResultDto(taskId,"rascunho","em_separacao",request.RowVersion+1,correlationId);} catch { tx.Rollback(); throw; }}
    public Task<TaskTransitionResultDto> ConfirmOrderAsync(Guid tenantId, Guid userId, Guid orderId, ConfirmOrderRequest request, string correlationId, CancellationToken ct)=>ConfirmAsync(tenantId,userId,orderId,request,correlationId,ct);
    public async Task<TaskTransitionResultDto> CompletePickingTaskAsync(Guid tenantId, Guid userId, Guid taskId, TaskChecklistDto checklist, string correlationId, CancellationToken ct){ ValidateContext(tenantId,userId); using var c=await connectionFactory.OpenConnectionAsync(ct); using var tx=c.BeginTransaction(); var t=await c.QuerySingleAsync<(Guid OrderId,string Status,long RowVersion)>(new CommandDefinition("select pedido_id OrderId,status Status,row_version RowVersion from integrarp.tarefa_operacional where tenant_id=@tenantId and id=@taskId for update",new{tenantId,taskId},tx,cancellationToken:ct)); if(t.Status!="em_execucao") {throw new InvalidOperationException("Tarefa deve estar em execução.");} await c.ExecuteAsync(new CommandDefinition("update integrarp.tarefa_operacional set status='concluida',checklist_resposta_json=@json::jsonb,row_version=row_version+1,atualizado_em=now() where tenant_id=@tenantId and id=@taskId; update integrarp.pedido set status='separado',row_version=row_version+1,atualizado_em=now() where tenant_id=@tenantId and id=@OrderId; insert into integrarp.pedido_historico_status(id,tenant_id,pedido_id,status_anterior,status_novo,usuario_id,correlation_id,criado_em) values(gen_random_uuid(),@tenantId,@OrderId,'em_separacao','separado',@userId,@correlationId,now()); insert into integrarp.outbox_evento(id,tenant_id,tipo,payload_json,status,tentativas,correlation_id,criado_em,atualizado_em) values(gen_random_uuid(),@tenantId,'pedido.separado',jsonb_build_object('pedidoId',@OrderId),'pendente',0,@correlationId,now(),now());",new{tenantId,userId,taskId,t.OrderId,json=System.Text.Json.JsonSerializer.Serialize(checklist.Items),correlationId},tx,cancellationToken:ct)); tx.Commit(); return new TaskTransitionResultDto(taskId,"em_execucao","concluida",t.RowVersion+1,correlationId);}
    public async Task<DashboardSummaryDto> GetDashboardAsync(Guid tenantId, Guid userId, CancellationToken ct){ ValidateContext(tenantId,userId); using var c=await connectionFactory.OpenConnectionAsync(ct); var q=await c.QuerySingleAsync<(int InProgress,int Awaiting,int Overdue,int Today,int Critical,int Reservations,int OutboxErrors)>(new CommandDefinition("select (select count(*) from integrarp.pedido where tenant_id=@tenantId and status in ('confirmado','em_separacao')) InProgress,(select count(*) from integrarp.pedido where tenant_id=@tenantId and status='rascunho') Awaiting,(select count(*) from integrarp.tarefa_operacional where tenant_id=@tenantId and vencimento_em<now() and status not in ('concluida','cancelada')) Overdue,(select count(*) from integrarp.tarefa_operacional where tenant_id=@tenantId and vencimento_em::date=current_date) Today,(select count(*) from integrarp.estoque_saldo s join integrarp.produto p on p.tenant_id=s.tenant_id and p.id=s.produto_id where s.tenant_id=@tenantId and (s.saldo_fisico-s.saldo_reservado)<p.estoque_minimo) Critical,(select count(*) from integrarp.estoque_reserva where tenant_id=@tenantId and status='ativa') Reservations,(select count(*) from integrarp.outbox_evento where tenant_id=@tenantId and status in ('erro','dead_letter')) OutboxErrors",new{tenantId},cancellationToken:ct)); return new DashboardSummaryDto(q.InProgress,q.Awaiting,q.Overdue,q.Today,q.Critical,q.Reservations,q.OutboxErrors,[],[],[]);}
    static void ValidateContext(Guid tenantId, Guid userId){ if(tenantId==default) throw new UnauthorizedAccessException("Tenant autenticado obrigatório."); if(userId==default) throw new UnauthorizedAccessException("Usuário autenticado obrigatório."); }
    static string? Normalize(string? value)=>string.IsNullOrWhiteSpace(value)?null:new string(value.Where(char.IsLetterOrDigit).ToArray()).ToUpperInvariant();
}
